class Solution { public long findMaximumElegance(int[][] items,int k){Arrays.sort(items,(a,b)->Integer.compare(b[0],a[0]));Set<Integer> categories=new HashSet<>();PriorityQueue<Integer> duplicates=new PriorityQueue<>();long sum=0;for(int i=0;i<k;i++){sum+=items[i][0];if(!categories.add(items[i][1]))duplicates.add(items[i][0]);}long answer=sum+(long)categories.size()*categories.size();for(int i=k;i<items.length&&!duplicates.isEmpty();i++)if(!categories.contains(items[i][1])){sum+=items[i][0]-duplicates.poll();categories.add(items[i][1]);answer=Math.max(answer,sum+(long)categories.size()*categories.size());}return answer;} }
